<script setup>
import { computed, ref } from 'vue';

const emptyForm = { name: 'Susana', paternal: 'Rojas', maternal: 'Merida', birth: '1992-08-22', role: 'Consultora', company: 'NOVA STUDIO', slogan: 'Ideas que dejan huella', qrUrl: 'https://ejemplo.com/mi-tarjeta' };
const form = ref({ ...emptyForm });
const generated = ref(false);
const copied = ref(false);
const avatarUrl = ref('');
const showBarcode = ref(false);
const showQr = ref(false);
const templates = [
    { id: 'aurora', name: 'Aurora', description: 'Violeta moderno', icon: '✦' },
    { id: 'ocean', name: 'Ocean', description: 'Azul profesional', icon: '◒' },
    { id: 'paper', name: 'Paper', description: 'Claro y elegante', icon: '◐' }
];
const selectedTemplate = ref('aurora');
const clean = (value) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z]/g, '');
const fullName = computed(() => [form.value.name, form.value.paternal, form.value.maternal].filter(Boolean).join(' '));
const displayName = computed(() => fullName.value || 'Tu nombre aparecerá aquí');
const initials = computed(() => fullName.value.split(' ').filter(Boolean).slice(0, 2).map((word) => word[0]).join('').toUpperCase() || 'SN');
const rfc = computed(() => { const paternal = clean(form.value.paternal); const maternal = clean(form.value.maternal); const name = clean(form.value.name); const date = form.value.birth.replaceAll('-', '').slice(2); return `${(paternal.slice(0, 2) + maternal.slice(0, 1) + name.slice(0, 1)).padEnd(4, 'X')}${date || '000000'}MCSRRS09`; });
function generateCard() { generated.value = true; copied.value = false; }
async function copyRfc() { try { await navigator.clipboard.writeText(rfc.value); copied.value = true; window.setTimeout(() => (copied.value = false), 1800); } catch { copied.value = false; } }
function resetForm() { form.value = { ...emptyForm }; generated.value = false; }
function selectImage(event) { const file = event.target.files?.[0]; if (!file) return; if (avatarUrl.value) URL.revokeObjectURL(avatarUrl.value); avatarUrl.value = URL.createObjectURL(file); event.target.value = ''; }
function removeImage() { if (avatarUrl.value) URL.revokeObjectURL(avatarUrl.value); avatarUrl.value = ''; }
const barcodeBars = computed(() => rfc.value.split('').flatMap((character) => { const code = character.charCodeAt(0); return [1 + (code % 3), 1 + ((code >> 2) % 3), 1 + ((code >> 4) % 2), 1 + ((code >> 5) % 3)]; }));
const qrImageUrl = computed(() => `https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=12&data=${encodeURIComponent(form.value.qrUrl || 'https://ejemplo.com/mi-tarjeta')}`);
</script>

<template>
    <main class="card-builder">
        <header class="page-heading">
            <div><p class="eyebrow"><span class="eyebrow-dot" /> Herramienta de identidad</p><h1>Genera tu tarjeta digital</h1><p class="subtitle">Completa tus datos y crea una tarjeta lista para compartir.</p></div>
            <div class="heading-badge"><i class="pi pi-sparkles" /> Vista previa en vivo</div>
        </header>
        <section class="builder-grid">
            <article class="builder-panel form-panel">
                <div class="panel-title"><div class="title-icon"><i class="pi pi-user-edit" /></div><div><h2>Datos personales</h2><p>La información se refleja en tiempo real.</p></div></div>
                <form @submit.prevent="generateCard">
                    <div class="form-row"><label>Nombre(s)<input v-model.trim="form.name" type="text" placeholder="Ej. Susana" /></label><label>Apellido paterno<input v-model.trim="form.paternal" type="text" placeholder="Ej. Rojas" /></label></div>
                    <div class="form-row"><label>Apellido materno<input v-model.trim="form.maternal" type="text" placeholder="Ej. Merida" /></label><label>Fecha de nacimiento<input v-model="form.birth" type="date" /></label></div>
                    <label>Ocupación<input v-model.trim="form.role" type="text" placeholder="Ej. Consultora" /></label>
                    <div class="form-row"><label>Nombre de empresa<input v-model.trim="form.company" type="text" placeholder="NOVA STUDIO" /></label><label>Frase corta<input v-model.trim="form.slogan" type="text" placeholder="Ideas que dejan huella" /></label></div>
                    <label>Enlace del código QR<input v-model.trim="form.qrUrl" type="url" placeholder="https://tusitio.com/contacto" /><small class="field-help"><i class="pi pi-link" /> Este enlace se abrirá al escanear la tarjeta.</small></label>
                    <div class="image-picker"><div><strong>Imagen de perfil</strong><small>JPG, PNG o WEBP · opcional</small></div><div class="image-actions"><label class="upload-button"><i class="pi pi-image" /> {{ avatarUrl ? 'Cambiar imagen' : 'Elegir imagen' }}<input type="file" accept="image/png,image/jpeg,image/webp" @change="selectImage" /></label><button v-if="avatarUrl" type="button" class="remove-image" @click="removeImage">Quitar</button></div></div>
                    <div class="template-picker"><div class="picker-heading"><div><strong>Plantilla visual</strong><small>Elige el estilo de tu tarjeta</small></div><i class="pi pi-palette" /></div><div class="template-options"><button v-for="template in templates" :key="template.id" type="button" class="template-option" :class="[{ active: selectedTemplate === template.id }, `template-${template.id}`]" @click="selectedTemplate = template.id"><span class="template-swatch">{{ template.icon }}</span><span><strong>{{ template.name }}</strong><small>{{ template.description }}</small></span><i v-if="selectedTemplate === template.id" class="pi pi-check" /></button></div></div>
                    <div class="rfc-field"><label>RFC generado</label><div class="rfc-control"><span>{{ rfc }}</span><button type="button" class="copy-button" :aria-label="copied ? 'RFC copiado' : 'Copiar RFC'" @click="copyRfc"><i :class="copied ? 'pi pi-check' : 'pi pi-copy'" /></button></div><small><i class="pi pi-info-circle" /> Se genera como identificador visual para tu tarjeta.</small></div>
                    <div class="form-actions"><button type="submit" class="primary-button"><i class="pi pi-sparkles" /> {{ generated ? 'Actualizar tarjeta' : 'Generar tarjeta' }}</button><button type="button" class="text-button" @click="resetForm">Limpiar</button></div>
                </form>
            </article>
            <article class="preview-panel">
                <div class="preview-toolbar"><div><span class="live-dot" /> Vista previa</div><span class="preview-hint">Formato vertical · 9:16</span></div>
                <div class="card-stage"><div class="digital-card" :class="`card-${selectedTemplate}`"><div class="card-glow glow-one" /><div class="card-glow glow-two" /><div class="card-topline"><div class="brand-symbol">N</div><div><strong>{{ form.company || 'NOVA STUDIO' }}</strong><small>{{ form.slogan || 'Ideas que dejan huella' }}</small></div></div><div class="card-orbit orbit-one" /><div class="card-orbit orbit-two" /><button type="button" class="avatar" :class="{ 'has-image': avatarUrl }" aria-label="Cambiar imagen de perfil" @click="$refs.avatarInput.click()"><img v-if="avatarUrl" :src="avatarUrl" alt="Imagen de perfil" /><span v-else>{{ initials }}</span><i class="pi pi-camera" /></button><input ref="avatarInput" class="hidden-file-input" type="file" accept="image/png,image/jpeg,image/webp" @change="selectImage" /><div class="card-copy"><span class="card-label">TARJETA PERSONAL</span><h3>{{ displayName }}</h3><p>{{ form.role || 'Tu ocupación' }}</p></div><div class="card-divider" /><div class="card-data"><div><span>IDENTIFICADOR</span><strong>{{ rfc }}</strong></div><div><span>CONTACTO DIGITAL</span><strong>Disponible en línea</strong></div></div><div class="card-footer"><span>Mi identidad, mi historia.</span><div class="card-actions"><button type="button" class="qr-placeholder" aria-label="Abrir código QR" @click="showQr = true"><i class="pi pi-qrcode" /></button><button type="button" class="barcode-button" aria-label="Abrir código de barras" @click="showBarcode = true"><i v-for="(bar, index) in barcodeBars" :key="index" :style="{ width: `${bar}px` }" /></button></div></div></div></div>
                <p class="preview-note"><i class="pi pi-shield" /> Tu información se procesa únicamente en esta pantalla.</p>
            </article>
        </section>
        <div v-if="showQr" class="qr-modal-backdrop" role="presentation" @click.self="showQr = false"><section class="qr-modal" role="dialog" aria-modal="true" aria-labelledby="qr-title"><button type="button" class="close-modal" aria-label="Cerrar código QR" @click="showQr = false"><i class="pi pi-times" /></button><span class="modal-icon"><i class="pi pi-qrcode" /></span><h2 id="qr-title">Tu código QR</h2><p>Escanea para abrir el enlace de tu tarjeta.</p><img :src="qrImageUrl" alt="Código QR de la tarjeta digital" /><strong>{{ form.qrUrl || 'https://ejemplo.com/mi-tarjeta' }}</strong><a class="open-link" :href="form.qrUrl || 'https://ejemplo.com/mi-tarjeta'" target="_blank" rel="noreferrer"><i class="pi pi-external-link" /> Abrir enlace</a></section></div>
        <div v-if="showBarcode" class="qr-modal-backdrop" role="presentation" @click.self="showBarcode = false"><section class="qr-modal barcode-modal" role="dialog" aria-modal="true" aria-labelledby="barcode-title"><button type="button" class="close-modal" aria-label="Cerrar código de barras" @click="showBarcode = false"><i class="pi pi-times" /></button><span class="modal-icon"><i class="pi pi-bars" /></span><h2 id="barcode-title">Tu código de barras</h2><p>Identificador visual generado con tu RFC.</p><div class="barcode-large"><i v-for="(bar, index) in barcodeBars" :key="index" :style="{ width: `${bar * 3}px` }" /></div><strong>{{ rfc }}</strong></section></div>
    </main>
</template>

